// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz the block number offset (to pick numbers with different mod 15) and a caller key
    function testFuzz_property(uint256 blockOffset, uint256 callerKey) public {
        callerKey = bound(callerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep blockOffset reasonably small but allow all residues mod 15
        blockOffset = bound(blockOffset, 0, 1000);

        // pick an EOA for the caller from the fuzzed key
        address caller = vm.addr(uint256(callerKey));

        // ensure the caller has funds to send 10 ether
        vm.deal(caller, 20 ether);

        // ensure time advances past stored pastBlockTime
        // first, warp to some time and invoke once to set pastBlockTime
        vm.warp(1 days);
        vm.prank(caller);
        // send initialization call: must send exactly 10 ether as contract requires
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "initialization call failed");

        // compute a target block number by adding offset to current block
        uint256 targetBlock = block.number + (blockOffset % 200) + 1; // +1 to ensure change

        // advance blocks to reach targetBlock
        // vm.roll allowed; use it to set block.number
        vm.roll(targetBlock);

        // ensure timestamp strictly increases relative to pastBlockTime
        // pastBlockTime was set to previous block timestamp; warp forward
        vm.warp(block.timestamp + 1);

        // check residue to determine expected behavior for reference contract
        uint256 residue = block.number % 15;

        // send the deciding call of exactly 10 ether from caller
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        // After the call, for the reference contract: if block.number % 15 == 0 then contract drained -> balance 0
        // Otherwise contract retains balance (some nonzero balance from before; since it started with 10 ether and only drains when condition met)
        // We assert the general rule about address(c).balance matching the reference's condition.

        if (residue == 0) {
            // reference: drained -> balance == 0
            assertTrue(address(c).balance == 0, "expected drained when block.number % 15 == 0");
        } else {
            // reference: not drained -> balance > 0
            assertTrue(address(c).balance > 0, "expected not drained when block.number % 15 != 0");
        }
    }
}
